// n8n hands the error trigger one item: { execution: {...}, workflow: {...} }
const e = $input.first().json;
const exec = e.execution || {};
const err = exec.error || {};
const workflow = (e.workflow && e.workflow.name) || 'unknown workflow';
const node = exec.lastNodeExecuted || (err.node && err.node.name) || 'unknown node';
const message = err.message || JSON.stringify(err).slice(0, 500);
const url = exec.url || '';
// Try to recover the lead id from whatever the failed node was working on.
let leadId = null;
try {
  const text = JSON.stringify(exec.lastNodeExecuted ? e : err);
  const m = text.match(/lead_[0-9a-f]{10}/);
  if (m) leadId = m[0];
} catch (ignored) {}
const alert = [
  `Automation failed after 3 tries: ${workflow}`,
  `Node: ${node}`,
  `Error: ${message}`,
  leadId ? `Lead: ${leadId}` : 'Lead: not identified',
  url ? `Execution: ${url}` : '',
].filter(Boolean).join('\n');
return [{ json: { workflow, node, message, lead_id: leadId, execution_url: url, alert, payload: { mode: exec.mode, id: exec.id, error: err } } }];
